'use strict';
// Each authored trail is independently checked for its letter transformation.
const PUZZLES = [
{title:'A change of heart',start:'HEART',steps:[["EARTH","A whole world, or just a handful in a flowerpot.","Our home planet."],["WATER","It can run for miles without taking a step.","It flows from a tap."],["STEAM","A kettle lets it off; so might an angry person.","Water in its gaseous form."]]},
{title:'Off the beaten path',start:'TRAIL',steps:[["TRIAL","It can end in a verdict or turn you into a subscriber.","A judge may preside over one."],["TRAIN","A line of thought, or a line of carriages.","A railway vehicle."],["GIANT","A fairy-tale villain with a towering advantage.","Jack meets one above the beanstalk."]]},
{title:'Something in the air',start:'NIGHT',steps:[["THING","An object whose name has gone missing from your memory.","A general word for an object."],["THINK","Do this outside the box when the usual ideas fail.","What you do when solving this."],["THANK","Give someone credit with a grateful word.","You ___ someone for a gift."]]},
{title:'Small wonders',start:'SPARE',steps:[["PEARS","Orchard fruit that sounds like it comes in twos.","Green or yellow cousins of apples."],["SPEAR","A weapon whose business end gets straight to the point.","A long shaft used for thrusting or throwing."],["SPARK","One may start an argument; another starts a fire.","A little flash from flint."]]},
{title:'All at sea',start:'COAST',steps:[["COATS","Painters apply them; people put them on.","Wear these over your clothes."],["BOATS","They have bows that never fire arrows.","Small vessels on water."],["BOOST","What a flat battery and low morale might both need.","An increase or encouragement."]]},
{title:'A clean slate',start:'STONE',steps:[["NOTES","They can be passed in class or held by a singer.","You might jot these in a notebook."],["TONES","Change these, and the same words can sound kinder.","Voices can have warm or harsh ones."],["ONSET","An ending has its opposite at this point.","The beginning of an illness or season."]]},
{title:'The great outdoors',start:'PLANT',steps:[["PLANE","It may fly over a workshop or smooth wood inside one.","An aircraft."],["PANEL","A wall section, or the experts sitting in judgment.","A group of experts at a conference."],["PETAL","A flower can lose one each time a lover asks a question.","A rose has many of these."]]},
{title:'A fresh perspective',start:'SMILE',steps:[["LIMES","Tart green wedges with a regular job behind the bar.","Sour fruits used in a mojito."],["MILES","You can put these on a car without loading its boot.","A unit longer than a kilometer."],["SLIME","The goo a movie monster might leave as a calling card.","A sticky toy you can stretch."]]},
{title:'Bright ideas',start:'LIGHT',steps:[["NIGHT","It falls without breaking a single bone.","The opposite of day."],["THING","An unnamed object, or a fashion when it becomes the latest one.","Pass me that ___ over there."],["THINK","Do this twice before making a rash decision.","Ponder or reason."]]},
{title:'Ready, set, grow',start:'SEED',steps:[["DEEDS","They can prove your character or your ownership.","Good ___ help other people."],["NEEDS","They belong on the shopping list before the wants.","Food and shelter are basic ones."],["DENSE","Like a forest with little room between its trees.","The opposite of sparse."]]},
{title:'In good time',start:'HASTE',steps:[["HEATS","Early races in which only some competitors go through.","Qualifying races held before a final."],["WHEAT","A field of it may end up as a row of loaves.","Bread is commonly made from it."],["WATCH","It can have hands, or be what you do with your eyes.","Observe, or a timepiece on your wrist."]]},
{title:'Creature comforts',start:'BEAR',steps:[["BARE","Like a cupboard with nothing left to offer.","Barefoot means your feet are this."],["BREAD","Something you can earn, then spend at a bakery.","A loaf from a bakery."],["BEARD","Growth that can turn a clean-cut chin into a hiding place.","Facial hair below the mouth."]]},
{title:'Written in the stars',start:'STAR',steps:[["START","A sudden fright, or the first step in a long project.","Begin."],["SMART","A compliment to your mind or the way you dress.","Clever or intelligent."],["STREAM","It can flow through a valley or bring a film to your screen.","Smaller than a river."]]},
{title:'A quiet moment',start:'LISTEN',steps:[["SILENT","Like an old film whose dialogue you have to read.","The opposite of noisy."],["TINSEL","A festive tree's sparkle, sold by the strand.","Sparkly Christmas decoration."],["INLETS","Where the sea reaches inland through narrow openings.","Small coastal bays or waterways."]]},
{title:'Room to bloom',start:'GARDEN',steps:[["DANGER","The reason a warning sign earns its place.","A warning sign alerts you to this."],["RANGED","Varied from one extreme to another.","Prices ___ from low to high."],["GRADE","A pupil hopes for a high one; a cyclist may dread a steep one.","A teacher gives you an A, B, or C."]]},
{title:'A silver lining',start:'CLOUD',steps:[["COULD","It promises a possibility, but never a certainty.","The past tense of can."],["COLD","An illness you catch, or a reception you would rather avoid.","How ice feels."],["GOLD","What a champion and a prospector might both go home with.","The metal of a first-place medal."]]},
{title:'A slice of life',start:'LEAST',steps:[["SLATE","A roof may be covered in it; a fresh start wipes it clean.","A dark, layered stone."],["STALE","Like yesterday's bread or a joke everyone has heard.","Bread left out too long becomes this."],["TALES","They may be fairy, tall, or told out of school.","Fairy ___ begin once upon a time."]]}
];
const day=Math.floor(Date.now()/86400000),dateKey=new Date().toISOString().slice(0,10),dailyIndex=((day-20705)%PUZZLES.length+PUZZLES.length)%PUZZLES.length;
const DEFAULT_SETTINGS={sound:false,haptics:true,reducedMotion:matchMedia('(prefers-reduced-motion: reduce)').matches,contrast:false,textSize:100};
let db;try{db=JSON.parse(localStorage.getItem('wordshift-v1'))||{games:{}}}catch{db={games:{}}}
if(!db.games)db.games={};db.settings={...DEFAULT_SETTINGS,...db.settings};
let mode='daily',index=dailyIndex,inputValue='',message='',error=false,audioContext;
const main=document.querySelector('#main'),modal=document.querySelector('#modal'),announcer=document.querySelector('#announcer');

function newGame(){return{step:0,hints:0,mistakes:0,reveals:0,help:{},inputs:{},solved:false,checked:false,gentle:false,rested:false,rating:''}}
function key(){return mode==='daily'?'daily:'+dateKey:'practice:'+index}
function game(){const k=key();db.games[k]||=newGame();db.games[k].help||={};db.games[k].inputs||={};return db.games[k]}
function save(){try{localStorage.setItem('wordshift-v1',JSON.stringify(db))}catch{toast('Your game is still open, but progress may not save after this tab closes.')}}
function announce(t){announcer.textContent='';requestAnimationFrame(()=>announcer.textContent=t)}
function toast(t){const el=document.querySelector('#toast');el.textContent=t;el.style.display='block';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>el.style.display='none',3000)}
function openModal(html){document.querySelector('#modal-content').innerHTML=html;modal.showModal();document.querySelector('#modal-content').querySelector('button,input,select,textarea')?.focus()}
function diff(a,b){let aa=a.split(''),bb=b.split('');for(let i=aa.length-1;i>=0;i--){const j=bb.indexOf(aa[i]);if(j>=0){aa.splice(i,1);bb.splice(j,1)}}return{remove:aa.join(''),add:bb.join('')}}
function sortLetters(s){return s.split('').sort().join('')}
function sameTransformation(source,guess,answer){const a=diff(source,guess),b=diff(source,answer);return sortLetters(a.add)===sortLetters(b.add)&&sortLetters(a.remove)===sortLetters(b.remove)}
function resultType(g){const assisted=Object.values(g.help||{}).some(h=>(h.stage||h.count||0)>=3||h.revealed);if(assisted||g.reveals)return{label:'Completed Chain',className:'assisted',symbol:'◆'};if(g.hints||g.gentle)return{label:'Clever Recovery',className:'nudged',symbol:'✦'};return{label:'Clean Chain',className:'clean',symbol:'✳'}}
function metrics(){const games=Object.entries(db.games),solved=games.filter(([,g])=>g.solved),dailyGames=games.filter(([k,g])=>k.startsWith('daily:')&&(g.solved||g.rested));return{total:solved.length,clean:solved.filter(([,g])=>resultType(g).className==='clean').length,days:dailyGames.length}}
function weekDots(){return Array.from({length:7},(_,i)=>{const d=day-6+i,k='daily:'+new Date(d*86400000).toISOString().slice(0,10),g=db.games[k],state=g?.solved?'played':g?.rested?'rested':'';return `<span class="day-dot ${state}" title="${state==='played'?'Puzzle completed':state==='rested'?'Rest day':'Open day'}"><i>${['S','M','T','W','T','F','S'][new Date(d*86400000).getUTCDay()]}</i></span>`}).join('')}
function applySettings(){document.documentElement.classList.toggle('high-contrast',db.settings.contrast);document.documentElement.classList.toggle('reduce-motion',db.settings.reducedMotion);document.documentElement.classList.toggle('text-large',db.settings.textSize===115);document.documentElement.classList.toggle('text-xlarge',db.settings.textSize===130);const b=document.querySelector('#sound');b?.setAttribute('aria-pressed',String(db.settings.sound));b?.setAttribute('aria-label',db.settings.sound?'Turn sound off':'Turn sound on');b?.classList.toggle('active',db.settings.sound)}
function tone(kind){if(!db.settings.sound)return;try{audioContext||=new(window.AudioContext||window.webkitAudioContext)();const notes={tap:[440,.04],wrong:[180,.12],hint:[520,.1],correct:[523,.12,659,.18],complete:[523,.12,659,.14,784,.28]}[kind]||[440,.05],start=audioContext.currentTime;for(let i=0,o=0;i<notes.length;i+=2){const osc=audioContext.createOscillator(),gain=audioContext.createGain();osc.type='sine';osc.frequency.value=notes[i];gain.gain.setValueAtTime(.0001,start+o);gain.gain.exponentialRampToValueAtTime(.055,start+o+.01);gain.gain.exponentialRampToValueAtTime(.0001,start+o+notes[i+1]);osc.connect(gain).connect(audioContext.destination);osc.start(start+o);osc.stop(start+o+notes[i+1]+.02);o+=notes[i+1]}}catch{}}
function haptic(pattern=10){if(db.settings.haptics&&navigator.vibrate)navigator.vibrate(pattern)}

function how(){openModal(`<span class="eyebrow">A small puzzle for today</span><h2>Change the letters.<br>Find the next word.</h2><ol><li>Begin with the word on the board.</li><li>Follow the letter instruction, then rearrange the letters to answer the clue.</li><li>Each answer becomes the starting word for the next shift.</li></ol><div class="example"><strong>CAT</strong> &nbsp; + R &nbsp; → &nbsp; <strong>CART</strong><br><small>“A little vehicle you push.”</small></div><p>No timer. No lives. Use a nudge whenever you need one, pause at any time, or choose Gentle mode on a low-energy day.</p><button class="primary modal-action" onclick="modal.close()">Let’s play ↗</button>`)}
function showStats(){const m=metrics();openModal(`<span class="eyebrow">Your little rituals, adding up</span><h2>Small moments together.</h2><div class="stat-grid"><div><b>${m.days}</b><span>Days enjoyed</span></div><div><b>${m.total}</b><span>Puzzles solved</span></div><div><b>${m.clean}</b><span>Clean chains</span></div></div><div class="week-card"><strong>Your last seven days</strong><div class="week-dots">${weekDots()}</div><small>Lime is a completed puzzle. A heart is a rest day. Empty days stay open—nothing breaks.</small></div><p>Progress is private and saved only on this device and browser. These statistics celebrate participation; they are not a measure of intelligence or health.</p>`)}
function comfort(){openModal(`<span class="eyebrow">Make Wordshift comfortable</span><h2>Your settings.</h2><div class="setting-list"><label><span>Sound effects<small>Quiet ticks and success chimes</small></span><input id="set-sound" type="checkbox" ${db.settings.sound?'checked':''}></label><label><span>Gentle haptics<small>Supported mobile devices only</small></span><input id="set-haptics" type="checkbox" ${db.settings.haptics?'checked':''}></label><label><span>Reduce motion<small>Removes shakes and traveling effects</small></span><input id="set-motion" type="checkbox" ${db.settings.reducedMotion?'checked':''}></label><label><span>High contrast<small>Strengthens text and borders</small></span><input id="set-contrast" type="checkbox" ${db.settings.contrast?'checked':''}></label><label class="size-setting"><span>Text size</span><select id="set-size"><option value="100" ${db.settings.textSize===100?'selected':''}>Standard</option><option value="115" ${db.settings.textSize===115?'selected':''}>Large</option><option value="130" ${db.settings.textSize===130?'selected':''}>Extra large</option></select></label></div><button class="primary modal-action" id="save-settings">Save settings</button>`);document.querySelector('#save-settings').onclick=()=>{db.settings.sound=document.querySelector('#set-sound').checked;db.settings.haptics=document.querySelector('#set-haptics').checked;db.settings.reducedMotion=document.querySelector('#set-motion').checked;db.settings.contrast=document.querySelector('#set-contrast').checked;db.settings.textSize=Number(document.querySelector('#set-size').value);save();applySettings();modal.close();toast('Comfort settings saved.')}}
function sidebar(){const m=metrics();return `<aside class="sidebar"><section class="note"><div class="symbol" aria-hidden="true">✳</div><h2>Same letters.<br>New possibilities.</h2><p>A small daily puzzle, made for quiet moments together.</p><button onclick="how()">Show me how it works ↗</button></section><section class="mini-card"><div class="eyebrow">Your shared ritual</div><div class="mini-metrics"><div class="metric"><strong>${m.days}</strong><span>days enjoyed</span></div><div class="metric"><strong>${m.clean}</strong><span>clean chains</span></div></div><div class="week-dots compact">${weekDots()}</div><p>Missed days stay open. Rest days count as care, not failure.</p></section></aside>`}
function setNav(view){document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view))}
function chain(p,g){return [p.start,...p.steps.map(s=>s[0])].map((word,i)=>{const visible=i===0||g.solved||g.step>=i;const current=!g.solved&&i===g.step+1;return `${i?'<span class="chain-line"></span>':''}<div class="chain-node ${visible?'done':''} ${current?'current':''}"><small>${i?'Shift '+i:'Start'}</small><b>${visible?word:'·'.repeat(word.length)}</b></div>`}).join('')}
function loadDraft(){const g=game();inputValue=g.inputs[g.step]||''}

function render(){setNav(mode==='daily'?'daily':'collection');const p=PUZZLES[index],g=game();loadDraft();main.innerHTML=`<div class="intro"><div><div class="eyebrow">${mode==='daily'?'Your daily dose of wordplay':'The collection · No waiting required'}</div><h1>${mode==='daily'?'A little change of mind.':p.title}</h1><p>${g.step&&!g.solved?'Continue when you’re ready.':'Three connected clues. One word that keeps on changing.'}</p></div><div class="date">${mode==='daily'?new Date().toLocaleDateString('en-GB',{day:'numeric',month:'short',year:'numeric',timeZone:'UTC'}):'Practice #'+String(index+1).padStart(2,'0')}<span>${mode==='daily'?'About five quiet minutes':'Take it at your own pace'}</span></div></div><div class="layout"><div><section class="game"><div class="game-top"><span class="badge">${mode==='daily'?'The daily shift':'Practice shift'}</span><div class="status-chip ${resultType(g).className}">${g.solved?resultType(g).label:g.gentle?'Gentle mode':'Shift '+Math.min(g.step+1,3)+' of 3'}</div></div><div class="word-chain" aria-label="Word chain progress">${chain(p,g)}</div><div id="play" class="play-area fade"></div><div class="game-bottom"><span>✧ No rush. Just a little word magic.</span><span>3 shifts · ${p.start.length}–${Math.max(p.start.length,...p.steps.map(s=>s[0].length))} letters</span></div></section><div class="under-game"><span>${mode==='daily'?'One puzzle. One little win for today.':'A little practice goes a long way.'}</span><button onclick="collection()">Explore the collection ↗</button></div></div>${sidebar()}</div>`;renderPlay()}

function renderPlay(){const p=PUZZLES[index],g=game(),el=document.querySelector('#play');
if(g.rested&&!g.solved){el.innerHTML=`<div class="success restful"><div class="success-icon">♡</div><div class="eyebrow">Rest day noted</div><h2>Rest is part of the journey.</h2><p>Today stays part of your shared ritual. The puzzle will still be here if you feel like playing later.</p><button class="primary" onclick="playAfterRest()">Play today’s puzzle</button></div>`;return}
if(g.solved){const result=resultType(g);el.innerHTML=`<div class="success final-success"><div class="celebration" aria-hidden="true">${Array.from({length:14},(_,i)=>`<i style="--i:${i}">✦</i>`).join('')}</div><div class="success-icon">${result.symbol}</div><div class="eyebrow">All three shifts complete</div><h2>Today’s little win.</h2><span class="result-badge ${result.className}">${result.label}</span><p>${p.title} — complete.<br>${g.mistakes} ${g.mistakes===1?'try':'tries'} missed · ${g.hints} helpful ${g.hints===1?'moment':'moments'}</p><div class="result-path">${[p.start,...p.steps.map(s=>s[0])].map(w=>`<span>${w}</span>`).join('<small aria-hidden="true">→</small>')}</div><div class="feeling"><span>How did today feel?</span>${['Light','Just right','Tricky'].map(v=>`<button class="feeling-button ${g.rating===v?'selected':''}" onclick="rate('${v}')">${v}</button>`).join('')}</div><div class="result-actions"><button class="primary" onclick="share()">Share your result ↗</button><button class="secondary" onclick="showExplanation()">View explanation</button><button class="secondary" onclick="collection()">Keep playing in the collection</button></div><p>${mode==='daily'?'One little shift closer to hello.':'Practice makes possibilities.'}</p></div>`;return}
const n=g.step,step=p.steps[n],source=n?p.steps[n-1][0]:p.start,op=diff(source,step[0]),help=g.help[n]||{};
if(g.checked){el.innerHTML=`<div class="success shift-success"><div class="success-icon">✓</div><div class="eyebrow">Shift ${n+1} complete</div><div class="solved-word">${step[0].split('').map((c,i)=>`<span class="tile" style="--i:${i}">${c}</span>`).join('')}</div><p>${step[1]}<br><strong>${step[2]}</strong></p><button class="primary check" onclick="next()">${n===2?'See today’s result':'On to shift '+(n+2)} <span>→</span></button></div>`;return}
const operation=operationText(source,step[0]);
el.innerHTML=`<div class="source-label">${n?'Your last answer':'Your starting word'}</div><div class="source">${source}</div><div class="operation" aria-label="${operation}">${op.remove?`<b class="remove">− ${op.remove}</b>`:''}${op.add?`<b class="add">+ ${op.add}</b>`:''}${op.add||op.remove?'<span>then rearrange</span>':'<span>↔ &nbsp; Rearrange only</span>'}</div><div class="down" aria-hidden="true">↓</div><h2 class="clue">${step[1]}</h2><div class="letter-count">${step[0].length} letters</div>${hintPanel(help,step,operation)}<form id="answer-form"><div class="answer-wrap"><div class="tiles" id="tiles" aria-hidden="true"></div><input id="answer" aria-label="Answer for shift ${n+1}, ${step[0].length} letters" autocomplete="off" autocapitalize="characters" spellcheck="false" maxlength="${step[0].length}" inputmode="text" aria-describedby="feedback"></div><div class="feedback ${error?'error':''}" id="feedback" role="status">${message||'Try a word whenever you’re ready.'}</div><button class="primary check" type="submit">Check my word <span>↵</span></button></form><div class="hint-row"><button class="text-btn hint-button" onclick="hint()">☼ &nbsp; ${hintLabel(help)}</button>${mode==='daily'&&!g.gentle?'<button class="text-btn" onclick="gentleMode()">♡ &nbsp; Gentle mode</button>':''}${mode==='daily'?'<button class="text-btn" onclick="restToday()">Rest for today</button>':''}</div>`;
const inp=document.querySelector('#answer');inp.value=inputValue;inp.addEventListener('input',()=>{inputValue=inp.value.toUpperCase().replace(/[^A-Z]/g,'').slice(0,step[0].length);inp.value=inputValue;g.inputs[n]=inputValue;save();drawTiles();if(inputValue.length===step[0].length)feedback('Word ready. Check it when you’re ready.')});inp.addEventListener('focus',drawTiles);inp.addEventListener('blur',drawTiles);inp.addEventListener('keyup',drawTiles);inp.addEventListener('click',drawTiles);document.querySelector('#answer-form').addEventListener('submit',e=>{e.preventDefault();check()});drawTiles()}

function operationText(source,answer){const op=diff(source,answer);if(!op.add&&!op.remove)return`Rearrange the same ${answer.length} letters.`;return`${op.remove?'Remove '+op.remove+'. ':''}${op.add?'Add '+op.add+'. ':''}Then rearrange all the letters.`}
function hintPanel(help,step,operation){const stage=help.stage||help.count||0;if(!stage)return'';return `<section class="hint-panel" aria-live="polite"><span>Helpful clue ${Math.min(stage,3)} of 3</span>${stage>=1?`<p><b>Nudge:</b> ${step[2]}</p>`:''}${stage>=2?`<p><b>Mechanism:</b> ${operation}</p>`:''}${stage>=3?`<p><b>Letter reveal:</b> The answer starts with <strong>${step[0][0]}</strong>.</p>`:''}</section>`}
function hintLabel(help){const stage=help.stage||help.count||0;return stage>=3?'All help shown':stage===2?'Reveal one letter':stage===1?'Explain the shift':'A little nudge'}
function drawTiles(){const inp=document.querySelector('#answer'),tiles=document.querySelector('#tiles');if(!inp||!tiles)return;const len=PUZZLES[index].steps[game().step][0].length,pos=inp.selectionStart??inputValue.length;tiles.innerHTML=Array.from({length:len},(_,i)=>`<span class="tile ${inputValue[i]?'filled':''} ${i===Math.min(pos,len-1)&&document.activeElement===inp?'focus':''}">${inputValue[i]||''}</span>`).join('')}
function feedback(t,bad=false,kind=''){message=t;error=bad;const f=document.querySelector('#feedback');if(!f)return;f.textContent=t;f.classList.toggle('error',bad);f.dataset.kind=kind;announce(t)}
function check(){const g=game(),p=PUZZLES[index],answer=p.steps[g.step][0],source=g.step?p.steps[g.step-1][0]:p.start;if(inputValue.length!==answer.length){feedback(`Add ${answer.length-inputValue.length} more ${answer.length-inputValue.length===1?'letter':'letters'}.`,true,'incomplete');tone('wrong');return}if(inputValue!==answer){g.mistakes++;save();const valid=sameTransformation(source,inputValue,answer);feedback(valid?'That shift works, but it does not solve this clue.':'The letters do not match this shift yet.',true,valid?'clue':'rule');document.querySelector('#play').classList.remove('soft-shake');requestAnimationFrame(()=>document.querySelector('#play').classList.add('soft-shake'));tone('wrong');haptic([15,30,15]);document.querySelector('#answer').focus();return}g.checked=true;g.inputs[g.step]=inputValue;message='';error=false;save();tone('correct');haptic(25);announce(`Correct. Shift ${g.step+1} complete.`);render()}
function next(){const g=game();g.checked=false;g.step++;if(g.step===3){g.solved=true;g.rested=false;g.completedAt=new Date().toISOString();tone('complete');haptic([20,40,35])}inputValue=g.inputs[g.step]||'';message='';error=false;save();render()}
function hint(){const g=game(),n=g.step;g.help[n]||={stage:0};const current=g.help[n].stage||g.help[n].count||0;if(current>=3){toast('All three helpful clues are already open.');return}g.help[n].stage=current+1;g.hints++;if(g.help[n].stage===3)g.reveals++;save();tone('hint');haptic(8);message='';renderPlay();announce(`Helpful clue ${g.help[n].stage} of 3 shown.`)}
function gentleMode(){const g=game();openModal(`<span class="eyebrow">A softer puzzle today</span><h2>Turn on Gentle mode?</h2><p>The first nudge will open now, and the next hints will remain available. Today still counts as a completed ritual—there is no penalty.</p><button class="primary modal-action" id="confirm-gentle">Use Gentle mode</button><button class="secondary modal-action" onclick="modal.close()">Keep the current clues</button>`);document.querySelector('#confirm-gentle').onclick=()=>{g.gentle=true;g.help[g.step]||={stage:0};if(!(g.help[g.step].stage||g.help[g.step].count)){g.help[g.step].stage=1;g.hints++}save();modal.close();render();toast('Gentle mode is ready.')}}
function restToday(){openModal(`<span class="eyebrow">Listen to your energy</span><h2>Rest for today?</h2><p>Nothing breaks and nothing is lost. Today will simply appear as a rest day in your shared journey.</p><button class="primary modal-action" id="confirm-rest">Mark today as rest</button><button class="secondary modal-action" onclick="modal.close()">Continue the puzzle</button>`);document.querySelector('#confirm-rest').onclick=()=>{const g=game();g.rested=true;g.restedAt=new Date().toISOString();save();modal.close();render();announce('Rest day noted.')}}
function playAfterRest(){const g=game();g.rested=false;save();render()}
function rate(v){const g=game();g.rating=v;save();renderPlay();toast(`Saved: ${v}.`)}
function showExplanation(){const p=PUZZLES[index];openModal(`<span class="eyebrow">How every shift worked</span><h2>${p.title}</h2><div class="explanation-list">${p.steps.map((s,i)=>`<section><span>${i+1}</span><div><strong>${i?p.steps[i-1][0]:p.start} → ${s[0]}</strong><p>${s[1]} <b>${s[2]}</b></p></div></section>`).join('')}</div><button class="primary modal-action" onclick="modal.close()">Done</button>`)}
function collection(){setNav('collection');main.innerHTML=`<div class="intro"><div><div class="eyebrow">Stay a little curious</div><h1>The collection.</h1><p>${PUZZLES.length} handcrafted trails. Pick a word and see where it takes you.</p></div></div><div class="collection-grid">${PUZZLES.map((p,i)=>{const g=db.games['practice:'+i];const state=g?.solved?resultType(g).label:g?.step||g?.checked||g?.inputs&&Object.values(g.inputs).some(Boolean)?`In progress · shift ${Math.min((g.step||0)+1,3)} of 3`:'3 connected clues';return `<button class="puzzle-card" onclick="playPractice(${i})"><div class="eyebrow">Shift ${String(i+1).padStart(2,'0')}</div><div class="card-word">${p.start}</div><h2>${p.title}</h2><div class="card-foot"><span>${g?.solved?'✓ ':''}${state}</span><span>↗</span></div></button>`}).join('')}</div>`}
function playPractice(i){index=i;mode='practice';message='';error=false;render();window.scrollTo({top:0,behavior:db.settings.reducedMotion?'auto':'smooth'})}
async function share(){const g=game(),result=resultType(g),text=`Wordshift ${mode==='daily'?dateKey:'Practice #'+(index+1)}\n${[0,1,2].map(n=>(g.help[n]?.stage||g.help[n]?.count||0)>=3?'◆':(g.help[n]?.stage||g.help[n]?.count)?'✦':'✳').join(' ')}\n${result.label} · 3/3 shifts\n${location.origin}`;try{await navigator.clipboard.writeText(text);toast('Spoiler-free result copied!')}catch{openModal('<h2>Your result</h2><p>Copy the text below to share.</p><textarea id="share-text" rows="6" style="width:100%;padding:12px;font:14px sans-serif"></textarea>');document.querySelector('#share-text').value=text}}

document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{if(b.dataset.view==='collection')collection();else{mode='daily';index=dailyIndex;message='';error=false;render()}});
document.querySelectorAll('.brand').forEach(a=>a.onclick=e=>{e.preventDefault();mode='daily';index=dailyIndex;message='';error=false;render()});
document.querySelector('#how').onclick=how;document.querySelector('#stats').onclick=showStats;document.querySelector('#comfort').onclick=comfort;
document.querySelector('#sound').onclick=()=>{db.settings.sound=!db.settings.sound;save();applySettings();if(db.settings.sound)tone('tap');toast(`Sound ${db.settings.sound?'on':'off'}.`)};
document.querySelector('#close').onclick=()=>modal.close();modal.addEventListener('click',e=>{if(e.target===modal){const r=modal.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)modal.close()}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&modal.open)modal.close();else if(e.key.toLowerCase()==='h'&&!modal.open&&document.querySelector('#answer')){e.preventDefault();hint()}});
document.querySelector('#about').onclick=()=>openModal('<span class="eyebrow">Hello, curious mind</span><h2>Welcome to Wordshift.</h2><p>Wordshift began as a small nightly word ritual for an expectant couple—a few quiet minutes to think, laugh, and enjoy something together while waiting to meet their baby.</p><p>Follow the letter changes, untangle three connected clues, and discover where one word can take you. There is no timer, pressure, or judgment here.</p><p>No account is needed. Your progress stays in this browser. Clearing browser data resets it.</p>');
applySettings();render();

function contactConfig(){
  const c=window.WORDSHIFT_CONTACT||{};
  const email=typeof c.email==='string'&&/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(c.email)?c.email:'';
  let donationUrl='';try{const u=new URL(c.donationUrl);if(u.protocol==='https:'&&!u.username&&!u.password)donationUrl=u.href}catch{}
  return {email,donationUrl};
}
function contact(){
  const c=contactConfig();
  openModal(`<span class="eyebrow">Good words are worth sharing</span><h2>Got a little word magic?</h2><p class="contact-intro">Suggest a puzzle, say hello, or talk promotions and partnerships.</p><form id="contact-form" class="contact-form"><label>What’s on your mind?<select name="topic" id="contact-topic"><option value="Puzzle suggestion">A puzzle suggestion</option><option value="Promotion or partnership">A promotion or partnership</option><option value="Feedback or bug report">Feedback or a bug report</option><option value="Something else">Something else</option></select></label><div class="contact-pair"><label>Your name<input name="name" autocomplete="name" maxlength="80" required placeholder="What should we call you?"></label><label>Your email<input name="email" type="email" autocomplete="email" maxlength="254" required placeholder="you@example.com"></label></div><label>Your message<textarea name="message" id="contact-message" minlength="10" maxlength="3000" required placeholder="Share your starting word, answer, and clue. Tell us how the letters change!"></textarea></label><p class="form-note" id="contact-status" role="status">${c.email?'This opens your email app with the message ready. Review it and press Send there. This website does not store your contact details.':'Contact is opening soon. Sending will be available once our contact address is connected.'}</p><button class="primary" type="submit" ${c.email?'':'disabled'}>Open email draft <span>↗</span></button></form>`);
  document.querySelector('#contact-topic').addEventListener('change',e=>{document.querySelector('#contact-message').placeholder=e.target.value==='Puzzle suggestion'?'Share your starting word, answer, and clue. Tell us how the letters change!':e.target.value==='Promotion or partnership'?'Tell us about your brand, your idea, and the best way to reach you.':'What would you like us to know?'});
  document.querySelector('#contact-form').addEventListener('submit',e=>{
    e.preventDefault();if(!c.email||!e.target.reportValidity())return;
    const data=new FormData(e.target),name=String(data.get('name')).trim(),reply=String(data.get('email')).trim(),body=String(data.get('message')).trim();
    if(!name||body.length<10){document.querySelector('#contact-status').textContent='Please add your name and a message of at least 10 characters.';return}
    const subject='[Wordshift Game] '+data.get('topic');
    const message='Source: Wordshift Game contact form\nWebsite: https://www.wordshift-game.online/\n\nName: '+name+'\nReply to: '+reply+'\nTopic: '+data.get('topic')+'\n\n'+body;
    location.href='mailto:'+encodeURIComponent(c.email)+'?subject='+encodeURIComponent(subject)+'&body='+encodeURIComponent(message);
    document.querySelector('#contact-status').textContent='Your message has not been sent by this website. Finish sending in your email app; your form is still here if you need it.';
  });
}
function support(){
  const c=contactConfig();
  openModal(`<div class="support-heart" aria-hidden="true">♡</div><span class="eyebrow">Keep the words flowing</span><h2>Support a little curiosity.</h2><p>If Wordshift brings a bright spot to your day, you can help make room for more puzzles.</p><section class="support-box"><h3>A small thank-you.</h3><p>Playing is free. Supporting is optional. Either way, we’re glad you’re here.</p></section>${c.donationUrl?'<a id="donation-link" class="primary modal-action" target="_blank" rel="noopener noreferrer">Support Wordshift ↗</a><p class="form-note">You’ll continue to our external donation page to review the amount and payment details.</p>':'<p>Donations aren’t open yet. In the meantime, sharing Wordshift or suggesting a puzzle is a lovely way to help.</p>'}<button class="text-btn support-alt" id="support-suggestion">Share a puzzle idea instead ↗</button>`);
  if(c.donationUrl)document.querySelector('#donation-link').href=c.donationUrl;
  document.querySelector('#support-suggestion').onclick=()=>{modal.close();contact()};
}
document.querySelector('#contact').onclick=contact;
document.querySelector('#support').onclick=support;
